// Shared platform URLs for the generated PDF exports.
// Kept here — not inside the generated `boilerplateLogo.ts` (regenerated by
// scripts/gen-icons.py, which would wipe hand-added constants) — so the QR
// target + label never drift between the two PDF last pages.

/**
 * Public create-account URL encoded by the QR on both PDF last pages, so a
 * scanned code lands a prospective user directly on sign-up.
 */
export const BOILERPLATE_PLATFORM_URL = "https://app.boilerplate.digital/register";

/** Human-readable domain printed under the QR (verification, not the full path). */
export const BOILERPLATE_PLATFORM_DOMAIN = "app.boilerplate.digital";
